#include <cstdint>
#include <cstring>
#include <optional>
#include <string>
#include <vector>

struct Operands { std::string reg; std::string rm; std::size_t length; };

std::string registerName(int number, int bits)
{
    static const char* const r64[]{ "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi" };
    static const char* const r32[]{ "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi" };
    if (number < 8) return bits == 64 ? r64[number] : r32[number];
    return "r" + std::to_string(number) + (bits == 64 ? "" : "d");
}

static std::string hex(std::uint64_t v)
{
    static const char* const HEX{ "0123456789abcdef" };
    std::string out;
    do { out.insert(out.begin(), HEX[v & 0xF]); v >>= 4; } while (v);
    return "0x" + out;
}

static std::string signedDisp(std::int64_t d, bool first)
{
    if (d < 0) return "-" + hex(static_cast<std::uint64_t>(-d));
    return (first ? "" : "+") + hex(static_cast<std::uint64_t>(d));
}

std::optional<Operands> decodeModRm(const std::vector<std::uint8_t>& code, std::size_t at, std::uint8_t rex, int bits)
{
    if (at >= code.size()) return std::nullopt;
    const std::uint8_t m{ code[at] };
    const int mod{ m >> 6 }, regField{ (m >> 3) & 7 }, rmField{ m & 7 };
    Operands out{ registerName(regField + ((rex & 4) ? 8 : 0), bits), "", 1 };
    if (mod == 3) { out.rm = registerName(rmField + ((rex & 1) ? 8 : 0), bits); return out; }

    std::string base, index;
    int scale{ 1 };
    bool ripRelative{ false };
    std::size_t dispSize{ mod == 1 ? 1u : mod == 2 ? 4u : 0u };
    std::size_t i{ at + 1 };
    if (rmField == 4)
    {
        if (i >= code.size()) return std::nullopt;
        const std::uint8_t sib{ code[i++] };
        const int s{ sib >> 6 }, idx{ ((sib >> 3) & 7) + ((rex & 2) ? 8 : 0) }, b{ sib & 7 };
        scale = 1 << s;
        if (idx != 4) index = registerName(idx, 64);
        if (b == 5 && mod == 0) dispSize = 4;
        else base = registerName(b + ((rex & 1) ? 8 : 0), 64);
    }
    else if (rmField == 5 && mod == 0) { ripRelative = true; dispSize = 4; }
    else base = registerName(rmField + ((rex & 1) ? 8 : 0), 64);

    if (i + dispSize > code.size()) return std::nullopt;
    std::int64_t disp{ 0 };
    if (dispSize == 1) disp = static_cast<std::int8_t>(code[i]);
    if (dispSize == 4) { std::int32_t d; std::memcpy(&d, &code[i], 4); disp = d; }
    out.length = i + dispSize - at;

    std::string inside;
    if (ripRelative) inside = "rip" + signedDisp(disp, false);
    else
    {
        inside = base;
        if (!index.empty()) inside += (inside.empty() ? "" : "+") + index + "*" + std::to_string(scale);
        if (disp != 0 || inside.empty()) inside += signedDisp(disp, inside.empty());
    }
    out.rm = std::string(bits == 64 ? "qword ptr [" : "dword ptr [") + inside + "]";
    return out;
}

