using Bytes = std::vector<std::uint8_t>;
static std::string rmOf(Bytes b, std::uint8_t rex, int bits) { auto o{ decodeModRm(b, 0, rex, bits) }; return o ? o->rm : "<none>"; }
static std::string regOf(Bytes b, std::uint8_t rex, int bits) { auto o{ decodeModRm(b, 0, rex, bits) }; return o ? o->reg : "<none>"; }

TEST("register names") {
    CHECK_EQ(registerName(0, 64), std::string("rax"));
    CHECK_EQ(registerName(5, 32), std::string("ebp"));
    CHECK_EQ(registerName(12, 64), std::string("r12"));
    CHECK_EQ(registerName(8, 32), std::string("r8d"));
}
TEST("register operands") {
    CHECK_EQ(rmOf({ 0xE5 }, 0x48, 64), std::string("rbp"));
    CHECK_EQ(regOf({ 0xE5 }, 0x48, 64), std::string("rsp"));
    CHECK_EQ(rmOf({ 0xC0 }, 0, 32), std::string("eax"));
    CHECK_EQ(regOf({ 0xC0 }, 0x4D, 64), std::string("r8"));
    CHECK_EQ(rmOf({ 0xC0 }, 0x4D, 64), std::string("r8"));
}
TEST("memory operands") {
    CHECK_EQ(rmOf({ 0x45, 0xFC }, 0, 32), std::string("dword ptr [rbp-0x4]"));
    CHECK_EQ(rmOf({ 0x41, 0x18 }, 0, 32), std::string("dword ptr [rcx+0x18]"));
    CHECK_EQ(rmOf({ 0x01 }, 0x48, 64), std::string("qword ptr [rcx]"));
    CHECK_EQ(rmOf({ 0x04, 0xC8 }, 0x48, 64), std::string("qword ptr [rax+rcx*8]"));
    CHECK_EQ(rmOf({ 0x44, 0x24, 0x28 }, 0x4C, 64), std::string("qword ptr [rsp+0x28]"));
    CHECK_EQ(rmOf({ 0x84, 0x24, 0x00, 0x01, 0x00, 0x00 }, 0, 32), std::string("dword ptr [rsp+0x100]"));
    CHECK_EQ(rmOf({ 0x44, 0x8D, 0x10 }, 0x43, 32), std::string("dword ptr [r13+r9*4+0x10]"));
}
TEST("rip-relative and no base") {
    CHECK_EQ(rmOf({ 0x0D, 0x10, 0x00, 0x00, 0x00 }, 0x48, 64), std::string("qword ptr [rip+0x10]"));
    CHECK_EQ(rmOf({ 0x05, 0xF0, 0xFF, 0xFF, 0xFF }, 0, 32), std::string("dword ptr [rip-0x10]"));
    CHECK_EQ(rmOf({ 0x04, 0x25, 0x10, 0x00, 0x00, 0x00 }, 0, 32), std::string("dword ptr [0x10]"));
    CHECK_EQ(rmOf({ 0x04, 0x8D, 0x10, 0x00, 0x00, 0x00 }, 0, 32), std::string("dword ptr [rcx*4+0x10]"));
}
TEST("lengths and truncation") {
    CHECK_EQ(decodeModRm({ 0xE5 }, 0, 0, 64)->length, 1u);
    CHECK_EQ(decodeModRm({ 0x45, 0xFC }, 0, 0, 32)->length, 2u);
    CHECK_EQ(decodeModRm({ 0x0D, 0, 0, 0, 0 }, 0, 0, 64)->length, 5u);
    CHECK_EQ(decodeModRm({ 0x84, 0x24, 0, 1, 0, 0 }, 0, 0, 32)->length, 6u);
    CHECK(!decodeModRm({ 0x45 }, 0, 0, 32).has_value());
    CHECK(!decodeModRm({ 0x04 }, 0, 0, 32).has_value());
    CHECK(!decodeModRm({}, 0, 0, 32).has_value());
}

